(1886050, 259858, 47487, '<td valign="top">ehhh... evocative image, but a bit of a stretch to meet the challenge...</td>', 'ehhh... evocative image, but a bit of a stretch to meet the challenge...', '2005-11-21 00:29:23.000000', NULL, 1),
