(1886057, 259798, 22734, '<td valign="top">A good take on the challenge.</td>', 'A good take on the challenge.', '2005-11-21 00:31:11.000000', NULL, 1),
(1886061, 258579, 29269, '<td valign="top">I thought that there will be something like this one! Nice execution, composition is very good but the lighting seems to be less than perfect. The specific thing that bothers me is the shadow of the left hand thumb on the cards, and the well-lighted ace in the sleeve. That means a different angle could have been perhaps more dramatic, if there was less contrast on the left hand and a spotlight on the sleeve... I''m not sure.</td>', 'I thought that there will be something like this one! Nice execution, composition is very good but the lighting seems to be less than perfect. The specific thing that bothers me is the shadow of the left hand thumb on the cards, and the well-lighted ace in the sleeve. That means a different angle could have been perhaps more dramatic, if there was less contrast on the left hand and a spotlight on the sleeve... I''m not sure.', '2005-11-21 00:31:59.000000', NULL, 1),
(1886062, 260137, 22734, '<td valign="top">Very entertaining and funny.</td>', 'Very entertaining and funny.', '2005-11-21 00:31:59.000000', NULL, 1),
(1886071, 258622, 22734, '<td valign="top">Intriguing b/w capture with strong tonal beauty and a great message.</td>', 'Intriguing b/w capture with strong tonal beauty and a great message.', '2005-11-21 00:34:01.000000', NULL, 1),
