(1886078, 260171, 6349, '<td valign="top">I''m going to guess this is a scalvert and a ribbon</td>', 'I''m going to guess this is a scalvert and a ribbon', '2005-11-21 00:35:09.000000', NULL, 1),
(1886092, 259750, 29269, '<td valign="top">Nice catch! One objection is the lack of focus on the motorist. The girl is the object of the photo, the motorist that should be the object is secondary, and would have been ignored if not for the challenge. A different crop perhaps?</td>', 'Nice catch! One objection is the lack of focus on the motorist. The girl is the object of the photo, the motorist that should be the object is secondary, and would have been ignored if not for the challenge. A different crop perhaps?', '2005-11-21 00:37:57.000000', NULL, 1),
(1886101, 260008, 23002, '<td valign="top">A great shot, but I am not sure it fits the challenge very well.  Great job to capture that expression though. 5</td>', 'A great shot, but I am not sure it fits the challenge very well.  Great job to capture that expression though. 5', '2005-11-21 00:39:41.000000', NULL, 1),
(1886104, 257656, 23002, '<td valign="top">Interesting use of lines in this shot.  I think the thimble is a bit too centered.</td>', 'Interesting use of lines in this shot.  I think the thimble is a bit too centered.', '2005-11-21 00:40:24.000000', NULL, 1),
