(1886112, 260122, 23002, '<td valign="top">A great shot spoiled by the background which is either too in focus or too out of focus depending on what your intentions were.</td>', 'A great shot spoiled by the background which is either too in focus or too out of focus depending on what your intentions were.', '2005-11-21 00:42:02.000000', NULL, 1),
(1886113, 259714, 29269, '<td valign="top">I can barely read from that paper... "In our marriage..."<br/>This image therefore relies a lot on the title, which I find wrong. The image is of a man, so if he''s not her husband, than she is the cheater as we do not know of his marital status. Better title would have been "She''s not his wife".<br/>Still, nice attempt but as I said it relies a lot on the title.</td>', 'I can barely read from that paper... "In our marriage..."This image therefore relies a lot on the title, which I find wrong. The image is of a man, so if he''s not her husband, than she is the cheater as we do not know of his marital status. Better title would have been "She''s not his wife".Still, nice attempt but as I said it relies a lot on the title.', '2005-11-21 00:42:03.000000', NULL, 1),
(1886118, 259746, 23002, '<td valign="top">Nicely done.  great sunset colour too.</td>', 'Nicely done.  great sunset colour too.', '2005-11-21 00:42:33.000000', NULL, 1),
