(1886254, 260143, 29269, '<td valign="top">For this image, the hand should have been in focus, and the letters on the wall should have been blurred, right? :-)</td>', 'For this image, the hand should have been in focus, and the letters on the wall should have been blurred, right? :-)', '2005-11-21 01:09:26.000000', NULL, 1),
(1886256, 259513, 47487, '<td valign="top">interesting idea, but the flash shadows are a bit distracting, and the whites are really washed out. I suppose the darkness/flash could be said to add to the ''clandestine'' feel of the situation, but, ehh.</td>', 'interesting idea, but the flash shadows are a bit distracting, and the whites are really washed out. I suppose the darkness/flash could be said to add to the ''clandestine'' feel of the situation, but, ehh.', '2005-11-21 01:09:41.000000', NULL, 1),
