(1889476, 258701, 46020, '<td valign="top">George. . . . Cheater extraordinaire!</td>', 'George. . . . Cheater extraordinaire!', '2005-11-22 12:46:14.000000', NULL, 1),
(1889629, 260122, 46651, '<td valign="top">Great macro. Are those vials and/or drugs in the background as well? Love the framing and the colors of this image. Suits challenge perfectly. How did you get the drop to be green? Interesting!</td>', 'Great macro. Are those vials and/or drugs in the background as well? Love the framing and the colors of this image. Suits challenge perfectly. How did you get the drop to be green? Interesting!', '2005-11-22 14:04:45.000000', NULL, 1),
(1889633, 259857, 22734, '<td valign="top">I just tried it this week and my taste buds were pleased. So this image can be taken in two ways: Pretending to eat the safe stuff, or so good that you can not tell the difference. Nice and sharp. Bumping up.</td>', 'I just tried it this week and my taste buds were pleased. So this image can be taken in two ways: Pretending to eat the safe stuff, or so good that you can not tell the difference. Nice and sharp. Bumping up.', '2005-11-22 14:08:04.000000', NULL, 1),
(1889669, 259823, 48386, '<td valign="top">AWW THIS IS SOOO CUTE!</td>', 'AWW THIS IS SOOO CUTE!', '2005-11-22 14:25:37.000000', NULL, 1),
(1889725, 260142, 811, '<td valign="top">The dramatic lighting really adds to this.  Nice twist on the hidden ace as well.</td>', 'The dramatic lighting really adds to this.  Nice twist on the hidden ace as well.', '2005-11-22 15:06:20.000000', NULL, 1),
(1889733, 259834, 40019, '<td valign="top">Ha, great capture!  Hope you didn''t get into an accident in trying to get this shot. :-)  Great focus and DOF for a moving picture (even if moving slowly).  I would have tried to remove some of the blue-ness of the picture in PS.</td>', 'Ha, great capture!  Hope you didn''t get into an accident in trying to get this shot. :-)  Great focus and DOF for a moving picture (even if moving slowly).  I would have tried to remove some of the blue-ness of the picture in PS.', '2005-11-22 15:09:11.000000', NULL, 1),
(1889735, 260091, 811, '<td valign="top">Neat idea, but I think a tighter crop so that the whole frame was filled would be more effective.</td>', 'Neat idea, but I think a tighter crop so that the whole frame was filled would be more effective.', '2005-11-22 15:09:35.000000', NULL, 1),
(1889737, 259117, 40019, '<td valign="top">I don''t wanna play cards with you!  Picture could have been a little sharper. Not sure why you went with B/W, the color of the cards and chips may have added some spark to the picture.</td>', 'I don''t wanna play cards with you!  Picture could have been a little sharper. Not sure why you went with B/W, the color of the cards and chips may have added some spark to the picture.', '2005-11-22 15:11:48.000000', NULL, 1),
(1889740, 259858, 40019, '<td valign="top">Ha!  Been there!  Nice capture - great title and subject for this audience.  Good rule of thirds usage - I like this one.</td>', 'Ha!  Been there!  Nice capture - great title and subject for this audience.  Good rule of thirds usage - I like this one.', '2005-11-22 15:13:50.000000', NULL, 1),
(1889741, 260127, 40019, '<td valign="top">Funny!  Good framing and lighting - nicely done.  Fits challenge well.</td>', 'Funny!  Good framing and lighting - nicely done.  Fits challenge well.', '2005-11-22 15:14:27.000000', NULL, 1),
(1889743, 260080, 40019, '<td valign="top">VERY creative!  Nicely done!  Great DOF and lighting.  Nice to see a gambling picture without 5 Aces.</td>', 'VERY creative!  Nicely done!  Great DOF and lighting.  Nice to see a gambling picture without 5 Aces.', '2005-11-22 15:16:08.000000', NULL, 1),
(1889747, 259133, 40019, '<td valign="top">Cute capture.  Good focus on the eye.</td>', 'Cute capture.  Good focus on the eye.', '2005-11-22 15:17:28.000000', NULL, 1),
(1889749, 259744, 40019, '<td valign="top">Now this is destined to become a DPC classic.  Nicely done!</td>', 'Now this is destined to become a DPC classic.  Nicely done!', '2005-11-22 15:18:43.000000', NULL, 1),
(1889769, 260181, 40019, '<td valign="top">Ha, boy would I have liked to do that!  I note a spot on the lower right of the picture that either did not get burned out all the way or was missed.  In Advanced Edit, you should look to burn/clone those out.  (FYI, tough to do when working with black - all depends on your monitor.  I totally missed the different blacks on my triptych 3rd picture.  I would suggest in these cases, when working with black, to look at the picture on different monitors to make sure you got it!)  Great theme!</td>', 'Ha, boy would I have liked to do that!  I note a spot on the lower right of the picture that either did not get burned out all the way or was missed.  In Advanced Edit, you should look to burn/clone those out.  (FYI, tough to do when working with black - all depends on your monitor.  I totally missed the different blacks on my triptych 3rd picture.  I would suggest in these cases, when working with black, to look at the picture on different monitors to make sure you got it!)  Great theme!', '2005-11-22 15:28:06.000000', NULL, 1),
(1889775, 259498, 40019, '<td valign="top">Funny!  Been there!  I hate that damn line - usually happens when you Strike as well.  Good theme.  I would have gone for a slightly deeper DOF.</td>', 'Funny!  Been there!  I hate that damn line - usually happens when you Strike as well.  Good theme.  I would have gone for a slightly deeper DOF.', '2005-11-22 15:29:31.000000', NULL, 1),
(1889776, 260177, 40019, '<td valign="top">Very cute. Nicely done.</td>', 'Very cute. Nicely done.', '2005-11-22 15:30:16.000000', NULL, 1),
