(1889818, 258903, 40019, '<td valign="top">Nice take on an over played subject for this challenge.  Great lighting and DOF - nice rich colors.  Good job.</td>', 'Nice take on an over played subject for this challenge.  Great lighting and DOF - nice rich colors.  Good job.', '2005-11-22 15:45:30.000000', NULL, 1),
