(1893520, 260137, 37875, '<td valign="top">imo, this image would have been much more effective with the visible bottom cropped out, leaving the boats to just float in the "sky".</td>', 'imo, this image would have been much more effective with the visible bottom cropped out, leaving the boats to just float in the "sky".', '2005-11-23 17:44:21.000000', NULL, 1),
(1893522, 259117, 37875, '<td valign="top">i like this version of the ace up the sleeve shot, because the ace is so subtle.  congrats on a well-executed version.</td>', 'i like this version of the ace up the sleeve shot, because the ace is so subtle.  congrats on a well-executed version.', '2005-11-23 17:44:28.000000', NULL, 1),
