(1893556, 259998, 37875, '<td valign="top">beautiful landscape.  love the lights at the base of the mountain.  the streak is small in comparison to the rest of the photo, so i''m not sure how much i buy the title with the image.  the image on its own, though, is stunning.</td>', 'beautiful landscape.  love the lights at the base of the mountain.  the streak is small in comparison to the rest of the photo, so i''m not sure how much i buy the title with the image.  the image on its own, though, is stunning.', '2005-11-23 17:46:24.000000', NULL, 1),
(1893557, 260140, 37875, '<td valign="top">the six card has a peachy cast to it which does not sit well with the b&amp;w, in my eye.  really like the choice of composition.</td>', 'the six card has a peachy cast to it which does not sit well with the b&w, in my eye.  really like the choice of composition.', '2005-11-23 17:46:27.000000', NULL, 1),
(1893559, 259714, 37875, '<td valign="top">the text in the picture is difficult to read because of the size, and i''m sure it lends more meaning to the scene in the photo.  i like the composition and soft lighting.</td>', 'the text in the picture is difficult to read because of the size, and i''m sure it lends more meaning to the scene in the photo.  i like the composition and soft lighting.', '2005-11-23 17:46:33.000000', NULL, 1),
(1893560, 260115, 37875, '<td valign="top">makes me sad...great idea for this challenge.<br/>great composition.  would like to see it with more diffused light so that it has less of a snapshot feel...</td>', 'makes me sad...great idea for this challenge.great composition.  would like to see it with more diffused light so that it has less of a snapshot feel...', '2005-11-23 17:46:38.000000', NULL, 1),
(1893561, 258832, 37875, '<td valign="top">there''s a bit of glare on the ace and other cards, but a very nice, simple composition.  i like it.</td>', 'there''s a bit of glare on the ace and other cards, but a very nice, simple composition.  i like it.', '2005-11-23 17:46:44.000000', NULL, 1),
