(1893573, 258514, 37875, '<td valign="top">nice use of selective desaturation.  would have been a more convincing anti-gravity effect if the model''s feet were not pointing down, imo.</td>', 'nice use of selective desaturation.  would have been a more convincing anti-gravity effect if the model''s feet were not pointing down, imo.', '2005-11-23 17:48:47.000000', NULL, 1),
