(1901030, 260179, 35078, '<td valign="top">Another really bad cheater! What ... is the dealer blind!!! I want in on this game!</td>', 'Another really bad cheater! What ... is the dealer blind!!! I want in on this game!', '2005-11-27 22:44:33.000000', NULL, 1),
(1901033, 259998, 33400, '<td valign="top">Beautiful image.  Kind of a stretch on the challenge, but I''m tired of playing cards and dice.  Thank you.</td>', 'Beautiful image.  Kind of a stretch on the challenge, but I''m tired of playing cards and dice.  Thank you.', '2005-11-27 22:44:59.000000', NULL, 1),
