INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1902668, 259889, 39145, '<td valign="top">I didn''t check to see if you got previous comments about this, but she''s holding a pencil and the theorems are clearly not written in pencil! Perhaps it was meant to be like a "hey look, I just got a 100 hundred on a ''number-2 pencil only'' test because of the cheat sheet i wrote with my sharpie this morning" type of thing?<br/> <br/>And this was a really cute idea! I''m embarrassed to admit I do this cheating action. And it also helps to write a cheat sheet in the cover of your calculator for math! Not that I cheat often or anything... Wow this comment makes me seem like a very bad student. Anyway, great job!</td>', 'I didn''t check to see if you got previous comments about this, but she''s holding a pencil and the theorems are clearly not written in pencil! Perhaps it was meant to be like a "hey look, I just got a 100 hundred on a ''number-2 pencil only'' test because of the cheat sheet i wrote with my sharpie this morning" type of thing? And this was a really cute idea! I''m embarrassed to admit I do this cheating action. And it also helps to write a cheat sheet in the cover of your calculator for math! Not that I cheat often or anything... Wow this comment makes me seem like a very bad student. Anyway, great job!', '2005-11-28 16:38:23.000000', NULL, 0),
